"""Frame arbiter: DFT single points on frames of Ar impacts generated by BOTH potentials, then DFT vs AIREBO vs MACE on the same frames.

Why: at the bridge site (70 eV) MACE gives a di-vacancy (3/3) and AIREBO none (0/5).  pushscan.py showed MACE is much closer to DFT for static
bond breaking.  This test checks dynamics-relevant geometries: a small 4x4 sheet (32 C + Ar, cheap enough for DFT) is hit by Ar with AIREBO+ZBL
and with MACE (same site, same energy, 0 K, own equilibrium lattice); frames are kept where the recipe allows DFT (Ar-C >= 1.6 A, C-C >= 1.0 A),
rescaled in-plane to the DFT lattice, and labelled.  Both potentials then evaluate ALL frames (AIREBO-made and MACE-made), so neither is judged
only on its own configurations.  Frames with the Ar further than --park A from the sheet get the Ar parked at that height (no Ar-C interaction
there) so that the deformed-sheet stage after the impact is also tested.  The closest-contact region (Ar-C < 1.6 A) is NOT covered: no DFT there.

    python framescan.py generate --airebo ../stageA_dft_check/CH.airebo --model data/ft/omat-0_all_ar/omat-0_all_ar.model --runs 2
    export OMP_NUM_THREADS=1
    nohup nice -n 10 mpirun -np 5 python dft_flow.py --pending data/framescan/pending.db --train data/framescan/labelled.db --workdir data/framescan > framescan_dft.log 2>&1 &
    python -W ignore framescan.py compare --airebo ../stageA_dft_check/CH.airebo --model data/ft/omat-0_all_ar/omat-0_all_ar.model
Impact points: the bridge centre plus a small random shift (--jitter) per run, so runs differ.
"""
import argparse
import json
import os
import shlex
import subprocess
import tempfile
from pathlib import Path

import numpy as np
from ase import Atoms, units
from ase.build import graphene
from ase.data import atomic_masses, atomic_numbers
from ase.db import connect
from ase.io import read, write

import recipe as R

p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
sp = p.add_subparsers(dest="cmd", required=True)
g = sp.add_parser("generate")
g.add_argument("--airebo", required=True)
g.add_argument("--model", default="")
g.add_argument("--lmp", default=os.environ.get("LMP_CMD", "lmp"))
g.add_argument("--dir", default="data/framescan")
g.add_argument("--src", default="../stageA_dft_check/dft_cheap/relaxed")
g.add_argument("--n", type=int, default=4)
g.add_argument("--proj", default="Ar")
g.add_argument("--site", default="bridge", choices=["top", "bridge"])
g.add_argument("--energy", type=float, default=70.0)
g.add_argument("--runs", type=int, default=2, help="impacts per potential")
g.add_argument("--frames", type=int, default=6, help="DFT frames kept per impact")
g.add_argument("--fs", type=float, default=300.0)
g.add_argument("--dump-fs", type=float, default=5.0)
g.add_argument("--height", type=float, default=6.0)
g.add_argument("--window", type=float, default=150.0, help="frames up to this long after first Ar-C contact (< 3 A) are candidates (fs)")
g.add_argument("--park", type=float, default=7.0)
g.add_argument("--jitter", type=float, default=0.15, help="random shift of the impact point (A)")
g.add_argument("--a0-airebo", type=float, default=2.419)
g.add_argument("--a0-mace", type=float, default=None, help="default: data/stageC/mace_thermal/a0.json, else 2.47")
g.add_argument("--threads", type=int, default=8)
c = sp.add_parser("compare")
c.add_argument("--airebo", required=True)
c.add_argument("--model", required=True)
c.add_argument("--lmp", default=os.environ.get("LMP_CMD", "lmp"))
c.add_argument("--dir", default="data/framescan")
c.add_argument("--threads", type=int, default=8)
args = p.parse_args()
D = Path(args.dir)
M_C = atomic_masses[6]


def site_xy(sheet, mode):
    cen = (sheet.cell[0, :2] + sheet.cell[1, :2]) / 2
    i = int(np.argmin(np.linalg.norm(sheet.positions[:, :2] - cen, axis=1)))
    if mode == "top":
        return sheet.positions[i, :2].copy()
    d = sheet.get_distances(i, range(len(sheet)), mic=True)
    d[i] = 9e9
    j = int(np.argmin(d))                                           # bridge: middle of the bond i-j
    return sheet.positions[i, :2] + sheet.get_distance(i, j, mic=True, vector=True)[:2] / 2


def flat_sheet(a0):
    sh = graphene(a=a0, size=(args.n, args.n, 1), vacuum=10.0)
    sh.pbc = (True, True, False)
    return sh


def put_projectile(sheet, mode, rng):
    at = sheet.copy()
    xy = site_xy(at, mode) + rng.uniform(-args.jitter, args.jitter, 2)
    z0 = at.positions[:, 2].mean()
    at += Atoms(args.proj, positions=[[xy[0], xy[1], z0 + args.height]])
    return at


# ------------------------------------------------------------------------------------------------ dynamics
def run_airebo(at, td):
    z = atomic_numbers[args.proj]
    td = Path(td)
    at = at.copy()
    at.set_initial_charges(np.zeros(len(at)))
    write(td / "s.data", at, format="lammps-data", specorder=["C", args.proj], atom_style="charge")
    vz = -np.sqrt(2 * args.energy / atomic_masses[z]) * units.fs * 1000.0
    dt = 0.05
    every = int(round(args.dump_fs / dt))
    (td / "in").write_text("\n".join([
        "units metal", "boundary p p m", "atom_style charge", "read_data s.data",
        f"mass 1 {M_C}", f"mass 2 {atomic_masses[z]}",
        "pair_style hybrid airebo 3.0 zbl 4.0 5.0", f"pair_coeff * * airebo {os.path.abspath(args.airebo)} C NULL",
        f"pair_coeff 2 2 zbl {z} {z}", f"pair_coeff 1 2 zbl 6.0 {z}", "neighbor 2.0 bin",
        f"group proj id {len(at)}", f"velocity proj set 0 0 {vz:.8f} units box", f"timestep {dt * 1e-3}", "fix i all nve",
        f"dump d all custom {every} t.dump id type x y z", "dump_modify d sort id", f"run {int(round(args.fs / dt))}"]))
    subprocess.run(shlex.split(args.lmp) + ["-in", "in", "-log", "none", "-screen", "none"], cwd=td, check=True)
    return read(td / "t.dump", format="lammps-dump-text", index=":", specorder=["C", args.proj])


_calc = None


def get_mace():
    global _calc
    if _calc is None:
        import torch
        torch.set_num_threads(args.threads)
        from mace.calculators import MACECalculator
        _calc = MACECalculator(model_paths=os.path.expanduser(args.model), device="cpu", default_dtype="float32")
    return _calc


def run_mace(at):
    from ase.md.verlet import VelocityVerlet
    at = at.copy()
    at.calc = get_mace()
    v = np.zeros((len(at), 3))
    v[-1, 2] = -np.sqrt(2 * args.energy / atomic_masses[atomic_numbers[args.proj]])
    at.set_velocities(v)
    dt = 0.2
    dyn = VelocityVerlet(at, timestep=dt * units.fs)
    frames = []
    every = int(round(args.dump_fs / dt))
    for s in range(int(round(args.fs / dt)) + 1):
        if s % every == 0:
            f = at.copy()
            f.calc = None
            frames.append(f)
        dyn.run(1)
    return frames


# ------------------------------------------------------------------------------------------------ frame selection
def to_dft_frame(fr, a_dft, a_src, n):
    """sheet+Ar frame -> recipe geometry on the DFT lattice; Ar parked at --park A above the plane if it is further away."""
    at = fr.copy()
    at.calc = None
    cell = np.array(at.cell)
    sc = a_dft / a_src
    at.positions[:, :2] *= sc
    cell[0] *= sc
    cell[1] *= sc
    at.set_cell(cell, scale_atoms=False)
    nc = len(at) - 1
    zpl = float(np.median(at.positions[:nc, 2]))
    zar = at.positions[-1, 2] - zpl
    if abs(zar) > args.park:
        at.positions[-1, 2] = zpl + args.park
        # wrap xy of the parked Ar into the cell (Ar left in its xy: periodic images are fine)
    at.wrap()
    at = R.normalise(at)
    return at, zar


def pick(frames, src_name, a_src, a_dft, rng_tag):
    cand = []
    t_contact = None
    for k, fr in enumerate(frames):
        at, zar = to_dft_frame(fr, a_dft, a_src, args.n)
        ok, margin = R.worst_pair(at)
        d = at.get_distances(len(at) - 1, range(len(at) - 1), mic=True)
        if t_contact is None and d.min() < 3.0:
            t_contact = k
        cand.append((k, at, ok, margin, float(d.min()), zar))
    if t_contact is None:
        return [], 0
    kmax = t_contact + int(round(args.window / args.dump_fs))
    good = [c for c in cand if c[2] and max(0, t_contact - 2) <= c[0] <= kmax]
    if not good:
        return [], 0
    idx = np.unique(np.linspace(0, len(good) - 1, min(args.frames, len(good))).round().astype(int))
    return [good[i] for i in idx], len(cand)


def generate():
    D.mkdir(parents=True, exist_ok=True)
    f = Path(args.src) / "gpaw_pristine_n4.extxyz"
    a_dft = float(np.linalg.norm(read(f).cell[0])) / args.n if f.exists() else 2.4704
    a_m = args.a0_mace
    if a_m is None:
        j = Path("data/stageC/mace_thermal/a0.json")
        a_m = json.loads(j.read_text())["a0"] if j.exists() else 2.47
    pdb = connect(D / "pending.db")
    have = {r.hash for r in pdb.select()}
    allf, new = [], 0
    for pot, a_src in (("airebo", args.a0_airebo), ("mace", a_m)):
        if pot == "mace" and not args.model:
            continue
        for run in range(args.runs):
            rng = np.random.default_rng(1000 * (pot == "mace") + run)
            at = put_projectile(flat_sheet(a_src), args.site, rng)
            if pot == "airebo":
                with tempfile.TemporaryDirectory() as td:
                    frames = run_airebo(at, td)
            else:
                from ase.optimize import FIRE
                sh = at[:-1]
                sh.calc = get_mace()
                FIRE(sh, logfile=None).run(fmax=0.01, steps=200)
                at.positions[:-1] = sh.positions
                frames = run_mace(at)
            sel, nfr = pick(frames, pot, a_src, a_dft, run)
            zmin = min((fr.positions[-1, 2] - np.median(fr.positions[:-1, 2])) for fr in frames)
            zend = frames[-1].positions[-1, 2] - np.median(frames[-1].positions[:-1, 2])
            print(f"{pot} run {run}: {len(frames)} frames, Ar min height {zmin:.2f} A, end height {zend:.1f} A -> {len(sel)} frames kept")
            for k, nf, ok, margin, dmin, zar in sel:
                t = k * args.dump_fs
                kind = f"{pot}_{args.site}_E{args.energy:g}_r{run}_t{t:.0f}fs"
                nf.info.update(kind=kind, family="frame", hash=R.structure_hash(nf))
                allf.append(nf)
                if nf.info["hash"] not in have:
                    pdb.write(nf, hash=nf.info["hash"], family="frame", kind=kind, margin=round(margin, 3), t_fs=t,
                              origin=pot, run=run, ar_c_min=round(dmin, 3), ar_height=round(zar, 2))
                    new += 1
                print(f"    t={t:5.0f} fs  Ar-C min {dmin:5.2f} A  Ar height {zar:6.2f} A  margin {margin:5.2f}")
    write(D / "geometries.extxyz", allf)
    print(f"\n{len(allf)} frames, {new} new rows in {D}/pending.db")
    print("next:\n  export OMP_NUM_THREADS=1\n  nohup nice -n 10 mpirun -np 5 python dft_flow.py --pending "
          f"{D}/pending.db --train {D}/labelled.db --workdir {D} > framescan_dft.log 2>&1 &")


# ------------------------------------------------------------------------------------------------ compare
def airebo_ef(at):
    z = atomic_numbers[args.proj] if False else 18
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        write(td / "s.data", at, format="lammps-data", specorder=["C", "Ar"], atom_style="atomic")
        (td / "in").write_text("\n".join([
            "units metal", "boundary p p p", "atom_style atomic", "read_data s.data", f"mass 1 {M_C}", f"mass 2 {atomic_masses[z]}",
            "pair_style hybrid airebo 3.0 zbl 4.0 5.0", f"pair_coeff * * airebo {os.path.abspath(args.airebo)} C NULL",
            f"pair_coeff 2 2 zbl {z} {z}", f"pair_coeff 1 2 zbl 6.0 {z}",
            "thermo_style custom step pe", "dump d all custom 1 f.dump id fx fy fz", "dump_modify d sort id", "run 0"]))
        subprocess.run(shlex.split(args.lmp) + ["-in", "in", "-log", "none", "-screen", "out.txt"], cwd=td, check=True)
        lines = (td / "out.txt").read_text().splitlines()
        e = next(float(lines[k + 1].split()[1]) for k, l in enumerate(lines) if l.split()[:2] == ["Step", "PotEng"])
        fl = (td / "f.dump").read_text().splitlines()
        f = np.array([[float(x) for x in l.split()[1:4]] for l in fl[9:9 + len(at)]])
    return e, f


def compare():
    import torch
    torch.set_num_threads(args.threads)
    from mace.calculators import MACECalculator
    mace = MACECalculator(model_paths=os.path.expanduser(args.model), device="cpu", default_dtype="float64")
    def kkey(r):
        k = r.kind
        return (k.split("_")[0], int(k.split("_r")[1].split("_")[0]), float(k.split("_t")[1][:-2]))
    rows = sorted(connect(D / "labelled.db").select(), key=kkey)
    out = []
    for r in rows:
        at = r.toatoms()
        e_a, f_a = airebo_ef(at)
        a2 = at.copy()
        a2.calc = mace
        e_m, f_m = a2.get_potential_energy(), a2.get_forces()
        fd = np.array(r.forces)
        ar = len(at) - 1 if at.get_chemical_symbols()[-1] == "Ar" else [i for i, s in enumerate(at.get_chemical_symbols()) if s == "Ar"][0]
        d = at.get_distances(ar, [i for i in range(len(at)) if i != ar], mic=True)
        c = [i for i in range(len(at)) if i != ar]
        zc = at.positions[c, 2]
        out.append(dict(kind=r.kind, origin=r.kind.split("_")[0], run=r.kind.split("_r")[1].split("_")[0], t=float(r.kind.split("_t")[1][:-2]),
                        dmin=float(d.min()), disp=float(np.abs(zc - np.median(zc)).max()),
                        E={"DFT": r.energy, "AIREBO": e_a, "MACE": e_m},
                        F={"AIREBO": f_a, "MACE": f_m}, fd=fd, ar=ar, c=c))
    print(f"{len(out)} labelled frames\n")
    groups = {}
    for o in out:
        groups.setdefault((o["origin"], o["run"]), []).append(o)
    print("energy relative to the first frame of the same impact (eV); force rms error vs DFT, all atoms (eV/A)")
    print(f"{'frame':30s} {'ArC':>5s} {'dispZ':>6s} {'dE DFT':>8s} {'dE AIR':>8s} {'dE MACE':>8s} {'F AIR':>7s} {'F MACE':>7s}")
    errs = {"AIREBO": [], "MACE": []}
    de_err = {"AIREBO": [], "MACE": []}
    for key, lst in groups.items():
        e0 = {n: lst[0]["E"][n] for n in lst[0]["E"]}
        for o in lst:
            fe = {n: np.sqrt(np.mean((o["F"][n] - o["fd"]) ** 2)) for n in ("AIREBO", "MACE")}
            de = {n: o["E"][n] - e0[n] for n in o["E"]}
            for n in errs:
                errs[n].append((o["F"][n] - o["fd"]).ravel())
                if o is not lst[0]:
                    de_err[n].append(de[n] - de["DFT"])
            print(f"{o['kind']:30s} {o['dmin']:5.2f} {o['disp']:6.2f} {de['DFT']:8.3f} {de['AIREBO']:8.3f} {de['MACE']:8.3f} {fe['AIREBO']:7.3f} {fe['MACE']:7.3f}")
    print("\nsummary over all frames")
    for n in errs:
        e = np.concatenate(errs[n])
        de = np.array(de_err[n])
        print(f"  {n:7s} force rms {np.sqrt(np.mean(e ** 2)):.3f} eV/A   energy-difference error: mean {de.mean():+.3f}, rms {np.sqrt(np.mean(de ** 2)):.3f}, max |.| {np.abs(de).max():.3f} eV")
    # split by frame origin and by Ar proximity
    print("\nforce rms error (eV/A) by group")
    for label, sel in (("frames made by AIREBO", lambda o: o["origin"] == "airebo"), ("frames made by MACE", lambda o: o["origin"] == "mace"),
                       ("Ar within 3 A of a C", lambda o: o["dmin"] < 3.0), ("Ar further than 3 A (deformed sheet)", lambda o: o["dmin"] >= 3.0),
                       ("sheet distorted > 0.5 A out of plane", lambda o: o["disp"] > 0.5)):
        s = [o for o in out if sel(o)]
        if not s:
            continue
        print(f"  {label:38s} n={len(s):2d}  " + "  ".join(
            f"{n}: {np.sqrt(np.mean(np.concatenate([(o['F'][n] - o['fd']).ravel() for o in s]) ** 2)):.3f}" for n in ("AIREBO", "MACE")))


if args.cmd == "generate":
    generate()
else:
    compare()
